#include <stdio.h>
#include <string.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("USAGE\n");
        return 0;
    }
    if (strcmp(argv[1], "to_camel") == 0) {
        // Convert to camel case
        char buffer[1024];
        fgets(buffer, 1024, stdin);
        buffer[strcspn(buffer, "\n")] = 0;
        int len = strlen(buffer);
        for (int i = 0; i < len; i++) {
            if (buffer[i] == '_') {
                buffer[i] = ' ';
            }
        }
        for (int i = 0; i < len; i++) {
            if (buffer[i] == ' ' && i + 1 < len) {
                buffer[i + 1] = toupper(buffer[i + 1]);
            }
        }
        printf("%s\n", buffer);
    } else if (strcmp(argv[1], "to_snake") == 0) {
        // Convert to snake case
        char buffer[1024];
        fgets(buffer, 1024, stdin);
        buffer[strcspn(buffer, "\n")] = 0;
        int len = strlen(buffer);
        for (int i = 0; i < len; i++) {
            if (isupper(buffer[i])) {
                buffer[i] = tolower(buffer[i]);
                if (i > 0) {
                    printf("_%c", buffer[i]);
                } else {
                    printf("%c", buffer[i]);
                }
            } else {
                printf("%c", buffer[i]);
            }
        }
        printf("\n");
    } else {
        printf("INVALID_MODE\n");
    }
    return 0;
}
